namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and their impact on civilization." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She received her PhD from MIT.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. He has published over 40 research papers.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "350", Title = "Database Systems", Description = "Relational database design, SQL, transaction management, and introduction to NoSQL databases.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez worked at Oracle for 10 years before joining academia. Her research focuses on distributed databases.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an award-winning educator with a passion for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "210", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Lisa Wang", InstructorBio = "Dr. Wang's research focuses on computational linear algebra and its applications in machine learning.", IsFeatured = false },
            new() { Id = 6, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab F 2:00–4:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist who previously worked at CERN on the Large Hadron Collider.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "220", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "TTh 9:00–10:15 AM", InstructorName = "Dr. Emily Nash", InstructorBio = "Dr. Nash specializes in electromagnetic theory and has developed novel antenna designs for satellite communications.", IsFeatured = false },
            new() { Id = 8, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "101", Title = "College Composition", Description = "Develop skills in academic writing, critical reading, and argumentation.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Prof. David Hart", InstructorBio = "Prof. Hart is a published author and has taught writing at the university level for over 20 years.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present day.", Credits = 3, Schedule = "TTh 1:00–2:15 PM", InstructorName = "Dr. Karen Mitchell", InstructorBio = "Dr. Mitchell is a specialist in 20th-century American fiction and has authored three books on the subject.", IsFeatured = true },
            new() { Id = 10, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World Civilizations", Description = "Survey of major world civilizations from antiquity to the modern era.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is a historian specializing in comparative civilizations and cross-cultural exchange.", IsFeatured = false },
            new() { Id = 11, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "315", Title = "The Renaissance", Description = "In-depth study of the European Renaissance, covering art, politics, science, and culture.", Credits = 3, Schedule = "TTh 3:30–4:45 PM", InstructorName = "Dr. Angela Russo", InstructorBio = "Dr. Russo has spent decades studying Renaissance Italy and frequently leads study-abroad programs in Florence.", IsFeatured = false },
            new() { Id = 12, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "440", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, and practical applications of AI.", Credits = 3, Schedule = "TTh 11:00 AM–12:15 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She received her PhD from MIT.", IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.DepartmentCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

