<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1 class="my-4">Enrollment Request</h1>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@selectedCourseTitle</strong> has been received.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    }
    else
    {
        <p>Fill out the form below to request enrollment in a course.</p>

        <form method="post" @formname="enrollment">
            <AntiforgeryToken />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required placeholder="e.g., STU-12345" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <select id="courseId" name="Model.CourseId" class="form-select" required>
                    <option value="">-- Select a course --</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.DepartmentCode @course.CourseNumber &mdash; @course.Title</option>
                    }
                </select>
            </div>

            <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-link">Cancel</a>
        </form>
    }
</div>

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;
    private string selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (Model.CourseId > 0 && !string.IsNullOrEmpty(Model.StudentName))
        {
            var course = Catalog.GetCourse(Model.CourseId);
            if (course is not null)
            {
                selectedCourseTitle = $"{course.DepartmentCode} {course.CourseNumber} — {course.Title}";
                Catalog.SubmitEnrollment(Model);
                submitted = true;
            }
        }
    }
}

