arguments.new_str:
[SupplyParameterFromForm] public EnrollmentRequest? Model { get; set; }
[SupplyParameterFromQuery] public int? CourseId { get; set; }

private List<Course> courses = new();
private bool submitted;
private string selectedCourseTitle = string.Empty;

protected override void OnInitialized()
{
    Model ??= new();
    courses = Catalog.GetCourses();

    if (CourseId.HasValue && Model.CourseId == 0)
    {
        Model.CourseId = CourseId.Value;
    }
}

protected override void OnParametersSet()
{
    if (Model is not null && Model.CourseId > 0 && !string.IsNullOrEmpty(Model.StudentName))
    {
        var course = Catalog.GetCourse(Model.CourseId);
        if (course is not null)
        {
            selectedCourseTitle = $"{course.DepartmentCode} {course.CourseNumber} — {course.Title}";
            Catalog.SubmitEnrollment(Model);
            submitted = true;
        }
    }
}

